INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(303578, 22169, 7038, '<td valign="top">Probably have more impact if you can more easily distinguish it is an eye there, can''t quite seem to make out the top part of the eye</td>', 'Probably have more impact if you can more easily distinguish it is an eye there, can''t quite seem to make out the top part of the eye', '2003-05-21 01:11:48.000000', NULL, 1),
(303580, 22165, 7038, '<td valign="top">I blood supposed to be orange? :P.  Good pic though</td>', 'I blood supposed to be orange? :P.  Good pic though', '2003-05-21 01:12:51.000000', NULL, 1),
(303583, 22028, 7038, '<td valign="top">Wrong challenge? I don''t get it</td>', 'Wrong challenge? I don''t get it', '2003-05-21 01:13:49.000000', NULL, 1),
(303587, 21783, 7038, '<td valign="top">Would have made more impact if you had a better background. Still not a bad pic though</td>', 'Would have made more impact if you had a better background. Still not a bad pic though', '2003-05-21 01:15:40.000000', NULL, 1),
(303588, 22177, 8155, '<td valign="top">Nice, seems a bit dark top right though.</td>', 'Nice, seems a bit dark top right though.', '2003-05-21 01:15:40.000000', NULL, 1),
(303589, 21673, 8155, '<td valign="top">Ummm a nice gadget but a bit to much empty space for my liking.</td>', 'Ummm a nice gadget but a bit to much empty space for my liking.', '2003-05-21 01:16:11.000000', NULL, 1),
(303591, 22029, 8155, '<td valign="top">A bit dark.</td>', 'A bit dark.', '2003-05-21 01:16:22.000000', NULL, 1),
(303592, 21660, 8155, '<td valign="top">Nice idea but a bit blurry. Was this dilibrete?</td>', 'Nice idea but a bit blurry. Was this dilibrete?', '2003-05-21 01:16:57.000000', NULL, 1),
(303594, 22138, 8155, '<td valign="top">Doesn''t seem a very good quality picture.</td>', 'Doesn''t seem a very good quality picture.', '2003-05-21 01:17:14.000000', NULL, 1),
(303597, 22076, 8624, '<td valign="top">very well done! great use of negative space and simple bold graphic elements. Very iconic. (I suppose I like this shot because I did a very similar concept, but you have executed it very well!) I like the translucent pills. I tried that it some of the rejected versions of my entry, but ended up using solid pills.</td>', 'very well done! great use of negative space and simple bold graphic elements. Very iconic. (I suppose I like this shot because I did a very similar concept, but you have executed it very well!) I like the translucent pills. I tried that it some of the rejected versions of my entry, but ended up using solid pills.', '2003-05-21 01:18:03.000000', NULL, 1),
(303598, 21893, 8155, '<td valign="top">At last, a different pair of sunglasses :) I like the background. A nice photo.</td>', 'At last, a different pair of sunglasses :) I like the background. A nice photo.', '2003-05-21 01:18:09.000000', NULL, 1),
(303602, 21736, 8155, '<td valign="top">The Matrix is a bunch of white stuff???</td>', 'The Matrix is a bunch of white stuff???', '2003-05-21 01:19:52.000000', NULL, 1),
(303603, 21812, 8155, '<td valign="top">Nice idea, bit more original than most.</td>', 'Nice idea, bit more original than most.', '2003-05-21 01:20:09.000000', NULL, 1),
(303610, 21942, 8155, '<td valign="top">Seems to be a lot of "noise" Is that what you pro''s call it???</td>', 'Seems to be a lot of "noise" Is that what you pro''s call it???', '2003-05-21 01:22:30.000000', NULL, 1),
(303613, 22043, 7038, '<td valign="top">Nice idea for the challenge</td>', 'Nice idea for the challenge', '2003-05-21 01:22:50.000000', NULL, 1),
(303615, 22134, 8624, '<td valign="top">nicely composed. I like the tones and the graininess in the face.</td>', 'nicely composed. I like the tones and the graininess in the face.', '2003-05-21 01:23:37.000000', NULL, 1),
(303616, 22084, 8155, '<td valign="top">It seems people will submit kids to every challenge under the sun. No offense, its a nice picture and all but its another kid! At least give her a gun or something. I wont give you a bad rating because its a kid though so don''t worry.</td>', 'It seems people will submit kids to every challenge under the sun. No offense, its a nice picture and all but its another kid! At least give her a gun or something. I wont give you a bad rating because its a kid though so don''t worry.', '2003-05-21 01:24:00.000000', NULL, 1),
(303620, 21958, 3419, '<td valign="top">A very creative interpretation of the movie. The web is well captured, and I don''t even mind the grain in the background. I do find the border distracting - perhaps thinner?</td>', 'A very creative interpretation of the movie. The web is well captured, and I don''t even mind the grain in the background. I do find the border distracting - perhaps thinner?', '2003-05-21 01:25:18.000000', NULL, 1),
(303623, 22063, 8624, '<td valign="top">very clever use of the mesh grid as a suggestion of pixelization. I would have rather seen it darker though. I like the drops of water in the random squares too. suggests noise in the system as well as duplicated copies of data.</td>', 'very clever use of the mesh grid as a suggestion of pixelization. I would have rather seen it darker though. I like the drops of water in the random squares too. suggests noise in the system as well as duplicated copies of data.', '2003-05-21 01:26:39.000000', NULL, 1),
(303626, 21807, 8624, '<td valign="top">nicely composed. I like the matrix data flow as the background element</td>', 'nicely composed. I like the matrix data flow as the background element', '2003-05-21 01:28:37.000000', NULL, 1),
(303627, 22155, 3419, '<td valign="top">Accurate interpretation of one of the definitions of matrix. I don''t really care for the lighting on the fossil. It looks a little washed out, colorless, and flat.</td>', 'Accurate interpretation of one of the definitions of matrix. I don''t really care for the lighting on the fossil. It looks a little washed out, colorless, and flat.', '2003-05-21 01:29:00.000000', NULL, 1),
(303629, 22209, 6565, '<td valign="top">Nice green tones, curious how you did the double image.</td>', 'Nice green tones, curious how you did the double image.', '2003-05-21 01:29:13.000000', NULL, 1),
(303631, 21678, 6900, '<td valign="top">Blue. 10.</td>', 'Blue. 10.', '2003-05-21 01:30:50.000000', NULL, 1),
(303632, 22017, 772, '<td valign="top">dam nice shot... best of show.. = 10</td>', 'dam nice shot... best of show.. = 10', '2003-05-21 01:31:13.000000', NULL, 1),
(303633, 22156, 6565, '<td valign="top">I think the color works more in this photo than the subject -- hard to tell what I''m seeing here.  Blur and graininess are ok because of the theme, I think.  I like the balance between light and dark.</td>', 'I think the color works more in this photo than the subject -- hard to tell what I''m seeing here.  Blur and graininess are ok because of the theme, I think.  I like the balance between light and dark.', '2003-05-21 01:31:35.000000', NULL, 1),
(303635, 22148, 8624, '<td valign="top">good lighting, altough I wish the catchlights on the glasses were even</td>', 'good lighting, altough I wish the catchlights on the glasses were even', '2003-05-21 01:32:47.000000', NULL, 1),
(303637, 22067, 6565, '<td valign="top">I think the lack of roundess in the circle is a bit distracting.  Is this the moon?  The image definitely sets a mood.</td>', 'I think the lack of roundess in the circle is a bit distracting.  Is this the moon?  The image definitely sets a mood.', '2003-05-21 01:33:20.000000', NULL, 1),
(303638, 22239, 5070, '<td valign="top">Altho'' I don''t consider it part of the theme, it is a very nice photo.</td>', 'Altho'' I don''t consider it part of the theme, it is a very nice photo.', '2003-05-21 01:33:57.000000', NULL, 1),
(303640, 22209, 8624, '<td valign="top">nice collage. the effect is well done.</td>', 'nice collage. the effect is well done.', '2003-05-21 01:34:26.000000', NULL, 1),
(303642, 22239, 6565, '<td valign="top">An interesting way to approach the challenge.  The image looks a little blurry to me, but I like the composition.  I''d have cropped just a bit more off the bottom.</td>', 'An interesting way to approach the challenge.  The image looks a little blurry to me, but I like the composition.  I''d have cropped just a bit more off the bottom.', '2003-05-21 01:35:32.000000', NULL, 1),
(303644, 22089, 6893, '<td valign="top">Nice use of your imagination.</td>', 'Nice use of your imagination.', '2003-05-21 01:36:54.000000', NULL, 1),
(303645, 22017, 8624, '<td valign="top">great lighting and tones and cool effect with the XRays. Good product palcement too! :)</td>', 'great lighting and tones and cool effect with the XRays. Good product palcement too! :)', '2003-05-21 01:37:15.000000', NULL, 1),
(303648, 22171, 3419, '<td valign="top">Nice and crisp - great focus. I like the composition - the angle in which you captured the building. Good colors too.</td>', 'Nice and crisp - great focus. I like the composition - the angle in which you captured the building. Good colors too.', '2003-05-21 01:37:51.000000', NULL, 1),
(303649, 22064, 6565, '<td valign="top">This photo looks very crisp -- I like the colors and the imagery.  Nice cropping, as well!</td>', 'This photo looks very crisp -- I like the colors and the imagery.  Nice cropping, as well!', '2003-05-21 01:38:33.000000', NULL, 1),
(303650, 21964, 3419, '<td valign="top">Very pretty, but too grainy for my taste. Perhaps some brighter lighting would help?</td>', 'Very pretty, but too grainy for my taste. Perhaps some brighter lighting would help?', '2003-05-21 01:38:34.000000', NULL, 1),
(303651, 21754, 6565, '<td valign="top">The only thing I don''t like is that the center of the image is a bit over-exposed.  Otherwise a very interesting composition!</td>', 'The only thing I don''t like is that the center of the image is a bit over-exposed.  Otherwise a very interesting composition!', '2003-05-21 01:39:17.000000', NULL, 1),
(303652, 21574, 3419, '<td valign="top">This would be a more stunning photo if the ?bead? detail was more in focus - all over. They are even blurry in the background.</td>', 'This would be a more stunning photo if the ?bead? detail was more in focus - all over. They are even blurry in the background.', '2003-05-21 01:41:07.000000', NULL, 1),
(303653, 22231, 6565, '<td valign="top">Great reproduction of an important scene from the movie!  And THEY had to use CG to do it!</td>', 'Great reproduction of an important scene from the movie!  And THEY had to use CG to do it!', '2003-05-21 01:42:59.000000', NULL, 1),
(303654, 21839, 6565, '<td valign="top">The image is really crisp, which is great.</td>', 'The image is really crisp, which is great.', '2003-05-21 01:43:18.000000', NULL, 1),
(303656, 22129, 6565, '<td valign="top">The pill is a little small for the overall composition, in my opinion.</td>', 'The pill is a little small for the overall composition, in my opinion.', '2003-05-21 01:44:20.000000', NULL, 1),
(303658, 22089, 6565, '<td valign="top">That''s one way to get your effects in!  I''d have composed this so that you couldn''t see the "click and drag" message.  Make em wonder.</td>', 'That''s one way to get your effects in!  I''d have composed this so that you couldn''t see the "click and drag" message.  Make em wonder.', '2003-05-21 01:45:12.000000', NULL, 1),
(303659, 22134, 1647, '<td valign="top">Great colour.  The graininess suits the industrial feel of the film wonderfully.</td>', 'Great colour.  The graininess suits the industrial feel of the film wonderfully.', '2003-05-21 01:45:30.000000', NULL, 1),
(303660, 21890, 3419, '<td valign="top">Very nice abstract. I like the colors and blurred detail.</td>', 'Very nice abstract. I like the colors and blurred detail.', '2003-05-21 01:45:50.000000', NULL, 1),
(303661, 22143, 6565, '<td valign="top">Nice shot!  The upper right of the photo is a bit empty, though... might have cropped in tighter on that side.</td>', 'Nice shot!  The upper right of the photo is a bit empty, though... might have cropped in tighter on that side.', '2003-05-21 01:45:57.000000', NULL, 1),
(303662, 22228, 1647, '<td valign="top">Unfortunaltely I don''t understand the reference really.  Having said that the photo is quite well executed.</td>', 'Unfortunaltely I don''t understand the reference really.  Having said that the photo is quite well executed.', '2003-05-21 01:46:08.000000', NULL, 1),
(303664, 22110, 6565, '<td valign="top">Use of blur is ok, but the white area is too overexposed and too much a part of the image for my taste.</td>', 'Use of blur is ok, but the white area is too overexposed and too much a part of the image for my taste.', '2003-05-21 01:46:29.000000', NULL, 1),
(303665, 22238, 3419, '<td valign="top">Oooo - very disturbing. I like your choice of green for color. Good composition.</td>', 'Oooo - very disturbing. I like your choice of green for color. Good composition.', '2003-05-21 01:46:58.000000', NULL, 1),
(303666, 21783, 6565, '<td valign="top">A nice clean shot, but the background is a little distracting.  Since you were going for a studio-type shot, I''d have made the background plain.</td>', 'A nice clean shot, but the background is a little distracting.  Since you were going for a studio-type shot, I''d have made the background plain.', '2003-05-21 01:47:11.000000', NULL, 1),
(303667, 22230, 1647, '<td valign="top">I''m guessing this is a focus-pull type shot of a matrix screen saver.  It''s quite an interesting shot and very well executed (assuming no rules were broken).</td>', 'I''m guessing this is a focus-pull type shot of a matrix screen saver.  It''s quite an interesting shot and very well executed (assuming no rules were broken).', '2003-05-21 01:47:21.000000', NULL, 1),
(303668, 22085, 6565, '<td valign="top">Nice -- only suggestion is to bring the background down in tone.  It''s almost gray on my monitor, and I can see the graininess because of it.</td>', 'Nice -- only suggestion is to bring the background down in tone.  It''s almost gray on my monitor, and I can see the graininess because of it.', '2003-05-21 01:47:51.000000', NULL, 1),
(303669, 21964, 1647, '<td valign="top">I don''t understand the reference to the Matrix challenge.</td>', 'I don''t understand the reference to the Matrix challenge.', '2003-05-21 01:48:01.000000', NULL, 1),
(303671, 22065, 6565, '<td valign="top">A bit blurry, would have liked reflective sunglasses to suggest the bending of reality.  Otherwise, nice composition.</td>', 'A bit blurry, would have liked reflective sunglasses to suggest the bending of reality.  Otherwise, nice composition.', '2003-05-21 01:48:32.000000', NULL, 1),
(303672, 22109, 5925, '<td valign="top">I''m glad to see somebody knows of the similarities between the Matrix and the Christ story!  I wondered if anyone here would get it.  :)  Good picture, wish it was bigger though.  Maybe black/white would have been more striking.</td>', 'I''m glad to see somebody knows of the similarities between the Matrix and the Christ story!  I wondered if anyone here would get it.  :)  Good picture, wish it was bigger though.  Maybe black/white would have been more striking.', '2003-05-21 01:48:36.000000', NULL, 1),
(303673, 21678, 1647, '<td valign="top">That''s a wonderful idea for the shot - and it ties in so well with the line from the Matrix.  Great idea and lovely execution.</td>', 'That''s a wonderful idea for the shot - and it ties in so well with the line from the Matrix.  Great idea and lovely execution.', '2003-05-21 01:48:58.000000', NULL, 1),
(303674, 22172, 6565, '<td valign="top">Unusual!  Unfortunately, the cranked-up saturation makes it look more like a pencil than a bullet.</td>', 'Unusual!  Unfortunately, the cranked-up saturation makes it look more like a pencil than a bullet.', '2003-05-21 01:49:13.000000', NULL, 1),
(303676, 21678, 3419, '<td valign="top">Good concept. I like how you even chose a "smoggy" looking photo to use.</td>', 'Good concept. I like how you even chose a "smoggy" looking photo to use.', '2003-05-21 01:49:34.000000', NULL, 1),
(303677, 21979, 1647, '<td valign="top">Wow - I love the focus effect you achieved.  I''m guessing the train you were on is moving with a long exposure.  I love the result.</td>', 'Wow - I love the focus effect you achieved.  I''m guessing the train you were on is moving with a long exposure.  I love the result.', '2003-05-21 01:49:45.000000', NULL, 1),
(303678, 21942, 8624, '<td valign="top">pills look oversaturated to me</td>', 'pills look oversaturated to me', '2003-05-21 01:52:01.000000', NULL, 1),
(303681, 22093, 6565, '<td valign="top">I like that this appears to actually BE green rather than be a photoshop job.  The cage effect as well as the reflection and abstract shapes are great.  Reminds me of children''s toys -- is that what they are?  Great interpretation of the challenge!</td>', 'I like that this appears to actually BE green rather than be a photoshop job.  The cage effect as well as the reflection and abstract shapes are great.  Reminds me of children''s toys -- is that what they are?  Great interpretation of the challenge!', '2003-05-21 01:55:24.000000', NULL, 1),
(303683, 22014, 6565, '<td valign="top">The cropping makes this image so much more interesting!  Nice work!</td>', 'The cropping makes this image so much more interesting!  Nice work!', '2003-05-21 01:57:17.000000', NULL, 1),
(303684, 21835, 1647, '<td valign="top">That''s really interesting.  Is it some kind of sea creature?</td>', 'That''s really interesting.  Is it some kind of sea creature?', '2003-05-21 01:58:16.000000', NULL, 1),
(303685, 22207, 6565, '<td valign="top">As cliche as it would have been, a green tint on this photo would have added some interest.  Overall, I like the composition a lot!</td>', 'As cliche as it would have been, a green tint on this photo would have added some interest.  Overall, I like the composition a lot!', '2003-05-21 01:58:31.000000', NULL, 1),
(303686, 21951, 6565, '<td valign="top">Adding the grid paper/fabric as the base really adds to this photo.</td>', 'Adding the grid paper/fabric as the base really adds to this photo.', '2003-05-21 01:59:00.000000', NULL, 1),
(303688, 22089, 1647, '<td valign="top">The idea is interesting but from a photography point of view I find it boring.  There''s too much photoshop skill and not enough genuine photography skill used.  For example your composition shows the windows Task Bar and even part of the System Tray - you could have at least cropped this out (I guess perhaps it was a deliberate inclusion)</td>', 'The idea is interesting but from a photography point of view I find it boring.  There''s too much photoshop skill and not enough genuine photography skill used.  For example your composition shows the windows Task Bar and even part of the System Tray - you could have at least cropped this out (I guess perhaps it was a deliberate inclusion)', '2003-05-21 02:00:26.000000', NULL, 1),
(303689, 22066, 8624, '<td valign="top">I like the high key exposure in her face.  I like the use of negative space and the texture in her coat. what is sticking out of her ear though?</td>', 'I like the high key exposure in her face.  I like the use of negative space and the texture in her coat. what is sticking out of her ear though?', '2003-05-21 02:01:31.000000', NULL, 1),
(303692, 21807, 6565, '<td valign="top">The shadow across the hand is the only thing that really bothers me about this photo.  I like how the spoon appears to be floating!</td>', 'The shadow across the hand is the only thing that really bothers me about this photo.  I like how the spoon appears to be floating!', '2003-05-21 02:03:07.000000', NULL, 1),
(303694, 21678, 8624, '<td valign="top">clever. nicely executed</td>', 'clever. nicely executed', '2003-05-21 02:05:11.000000', NULL, 1),
(303695, 22095, 7151, '<td valign="top">Alright, if this is what I think it is, that''s just gross.  Just had surgery four months ago, and this looks like the drainage tube that collected the puss and fluid out of my incision.  Beyond that, there''s no real focus (subject wise) and is very blurry.  I suppose that could be an "artistic" choice, but it doesn''t work for me.</td>', 'Alright, if this is what I think it is, that''s just gross.  Just had surgery four months ago, and this looks like the drainage tube that collected the puss and fluid out of my incision.  Beyond that, there''s no real focus (subject wise) and is very blurry.  I suppose that could be an "artistic" choice, but it doesn''t work for me.', '2003-05-21 02:05:16.000000', NULL, 1),
(303696, 22151, 6565, '<td valign="top">I tried several shots along these lines.  This works better than any of mine did! :)</td>', 'I tried several shots along these lines.  This works better than any of mine did! :)', '2003-05-21 02:07:38.000000', NULL, 1),
(303697, 22219, 8624, '<td valign="top">I think this could have been pretty effective without the negative effect</td>', 'I think this could have been pretty effective without the negative effect', '2003-05-21 02:07:42.000000', NULL, 1),
(303701, 21752, 6565, '<td valign="top">If this weren''t just the slightest bit tilted, I''d like it a lot better.</td>', 'If this weren''t just the slightest bit tilted, I''d like it a lot better.', '2003-05-21 02:10:45.000000', NULL, 1),
(303702, 22231, 7033, '<td valign="top">This has to be the absolutely best idea for this challenge! Too bad the light didn''t cooperate or I would have given this a 10. Wish I could make out the blue color just a bit better. Nice creativity -7</td>', 'This has to be the absolutely best idea for this challenge! Too bad the light didn''t cooperate or I would have given this a 10. Wish I could make out the blue color just a bit better. Nice creativity -7', '2003-05-21 02:12:48.000000', NULL, 1),
(303703, 22229, 6565, '<td valign="top">A little too much of the screen in the photo -- would have shifted downward to make it more interesting, but that''s just me. :)</td>', 'A little too much of the screen in the photo -- would have shifted downward to make it more interesting, but that''s just me. :)', '2003-05-21 02:13:14.000000', NULL, 1),
(303705, 21812, 6565, '<td valign="top">I like the dreamy feel to this image.  It really works!  And the "guy in the red coat" is no "woman in the red dress," but he does stand out very well.</td>', 'I like the dreamy feel to this image.  It really works!  And the "guy in the red coat" is no "woman in the red dress," but he does stand out very well.', '2003-05-21 02:14:28.000000', NULL, 1),
(303707, 22177, 7033, '<td valign="top">Something about this photo just doesn''t work. It''s too busy, maybe. I like your "confused" actor and the shot of the character garble is very clear. I think the smoke detracts from the shot. I would have lost the smoke and had the lighting be more direct or mainstream. Nice interpretation. I do like your choice of green in this picture. I kind of think she should be wearing black or at least pants. Nice job, though.</td>', 'Something about this photo just doesn''t work. It''s too busy, maybe. I like your "confused" actor and the shot of the character garble is very clear. I think the smoke detracts from the shot. I would have lost the smoke and had the lighting be more direct or mainstream. Nice interpretation. I do like your choice of green in this picture. I kind of think she should be wearing black or at least pants. Nice job, though.', '2003-05-21 02:15:26.000000', NULL, 1),
(303708, 22063, 6565, '<td valign="top">NIce work!  The moisture on the screen adds a great deal.  I did some screen photos but none worked quite right for me.  This one works beautifully!</td>', 'NIce work!  The moisture on the screen adds a great deal.  I did some screen photos but none worked quite right for me.  This one works beautifully!', '2003-05-21 02:16:03.000000', NULL, 1),
(303709, 22161, 7033, '<td valign="top">hmmm. Sounds like a quote from the new movie (which most of us probably haven''t seen yet). I like your choice of subject and I don''t know how you got your background to work like that but it does seem to drape in a distractying way. I wish the statue was a bit brighter, although I like the direction of the light.</td>', 'hmmm. Sounds like a quote from the new movie (which most of us probably haven''t seen yet). I like your choice of subject and I don''t know how you got your background to work like that but it does seem to drape in a distractying way. I wish the statue was a bit brighter, although I like the direction of the light.', '2003-05-21 02:17:06.000000', NULL, 1),
(303711, 22135, 7033, '<td valign="top">I''m beginning to feel like I don''t know enough about the Matrix to judge. But I can say that the word NOKIA staring at you does make it kind of hard to get swept away into the photograph. I LOVE your background. I think if you would have lost the phone, it still would have been an interesting shot (it''s still complex even though everyone knows it''s a motherboard). You have great focus and lighting in this shot. Good job. -7</td>', 'I''m beginning to feel like I don''t know enough about the Matrix to judge. But I can say that the word NOKIA staring at you does make it kind of hard to get swept away into the photograph. I LOVE your background. I think if you would have lost the phone, it still would have been an interesting shot (it''s still complex even though everyone knows it''s a motherboard). You have great focus and lighting in this shot. Good job. -7', '2003-05-21 02:19:54.000000', NULL, 1),
(303712, 21882, 6565, '<td valign="top">The movement in this photo is disturbing!  If it were on the square it''d be a 10 in my book.</td>', 'The movement in this photo is disturbing!  If it were on the square it''d be a 10 in my book.', '2003-05-21 02:20:12.000000', NULL, 1),
(303713, 21928, 7033, '<td valign="top">Whoa, that is cool. It took me a minute, but I did figure it out. You are a bit hot in spots, but I love the dimension you gave this subject and your choice of green is intriguing. NIce job.</td>', 'Whoa, that is cool. It took me a minute, but I did figure it out. You are a bit hot in spots, but I love the dimension you gave this subject and your choice of green is intriguing. NIce job.', '2003-05-21 02:21:21.000000', NULL, 1),
(303716, 21796, 6565, '<td valign="top">I feel like the lighting is a problem here -- too much light behind, not enough in front.  The composition is very nice, though!</td>', 'I feel like the lighting is a problem here -- too much light behind, not enough in front.  The composition is very nice, though!', '2003-05-21 02:27:45.000000', NULL, 1),
