(304692, 22064, 6325, '<td valign="top">The border works well. One of the best phone/sunglasses shots.</td>', 'The border works well. One of the best phone/sunglasses shots.', '2003-05-22 00:05:33.000000', NULL, 1),
(304693, 21777, 8056, '<td valign="top">If you manage to turn the white wording into greenish, the impression of this pic will totally changed. the color contrast of this pic is not strong enough. Can u imagine my words? lack of freaking feeling with this color contrast</td>', 'If you manage to turn the white wording into greenish, the impression of this pic will totally changed. the color contrast of this pic is not strong enough. Can u imagine my words? lack of freaking feeling with this color contrast', '2003-05-22 00:09:24.000000', NULL, 1),
(304694, 22043, 4007, '<td valign="top">Wow.. this is a perfect shot.. from the blurred focus to the seemly merger of the hands to the green tones.  Excellent work. My only complain might be the negative space at the top.. but it doesn''t really detract, it just doesn''t seem to add anything. 10</td>', 'Wow.. this is a perfect shot.. from the blurred focus to the seemly merger of the hands to the green tones.  Excellent work. My only complain might be the negative space at the top.. but it doesn''t really detract, it just doesn''t seem to add anything. 10', '2003-05-22 00:11:18.000000', NULL, 1),
(304697, 22129, 4007, '<td valign="top">Nice job working in the cypher quote... and nice detail on the photo.</td>', 'Nice job working in the cypher quote... and nice detail on the photo.', '2003-05-22 00:16:47.000000', NULL, 1),
(304699, 22239, 7743, '<td valign="top">I like the reflection.  The image is a little dark and the cut apple is too central.  Maybe if the items were more on the diagonal they might have more impact.</td>', 'I like the reflection.  The image is a little dark and the cut apple is too central.  Maybe if the items were more on the diagonal they might have more impact.', '2003-05-22 00:17:07.000000', NULL, 1),
(304700, 21660, 7743, '<td valign="top">Since the offset of all objects in the image is too uniform I assume this was done on purpose.  My eyes keep wanting to focus on something.  Maybe trying the photo with close to zero DOF would help.</td>', 'Since the offset of all objects in the image is too uniform I assume this was done on purpose.  My eyes keep wanting to focus on something.  Maybe trying the photo with close to zero DOF would help.', '2003-05-22 00:19:21.000000', NULL, 1),
