(304714, 22126, 7743, '<td valign="top">Too dark and grainy.  It reminds me of the Blair Witch Project rather than the Matrix.</td>', 'Too dark and grainy.  It reminds me of the Blair Witch Project rather than the Matrix.', '2003-05-22 00:29:35.000000', NULL, 1),
(304715, 22132, 4007, '<td valign="top">Good choice with the black and white.. the patterns and lines in this shot come out from all over and create a very slick scene.  The water adds the perfect touch to the shot by mixing up the patterns and structure. 9</td>', 'Good choice with the black and white.. the patterns and lines in this shot come out from all over and create a very slick scene.  The water adds the perfect touch to the shot by mixing up the patterns and structure. 9', '2003-05-22 00:31:13.000000', NULL, 1),
