(304717, 21784, 7743, '<td valign="top">Nice reflection in a car.  I would have liked to see more emphasis on the reflection rather than the name plate.</td>', 'Nice reflection in a car.  I would have liked to see more emphasis on the reflection rather than the name plate.', '2003-05-22 00:33:02.000000', NULL, 1),
(304718, 21807, 4007, '<td valign="top">If the shadow on the hand could have been avoided it would have added to the surreal nature of this shot.</td>', 'If the shadow on the hand could have been avoided it would have added to the surreal nature of this shot.', '2003-05-22 00:34:18.000000', NULL, 1),
