(306486, 21807, 4411, '<td valign="top">Very clear shot, well executed and fitting into the challenge well.<br/>The hand lacks detail, maybe lost in processing, but the image is still very effective.</td>', 'Very clear shot, well executed and fitting into the challenge well.The hand lacks detail, maybe lost in processing, but the image is still very effective.', '2003-05-25 18:59:04.000000', NULL, 1),
(306488, 22076, 4411, '<td valign="top">A lot more than ''just a photo of sunglasses &amp; pills'' this is very well done.<br/>The white background is very effective and the colours very strong. Maybe too much empty space top &amp; bottom, but a great shot.</td>', 'A lot more than ''just a photo of sunglasses & pills'' this is very well done.The white background is very effective and the colours very strong. Maybe too much empty space top & bottom, but a great shot.', '2003-05-25 19:01:52.000000', NULL, 1),
(306492, 22118, 4411, '<td valign="top">Automatic zero for including Bill Gates in this. No, hold on there is no 0 vote, I''ll have to add 1 ...<br/>1 + 0 = 10<br/>: )</td>', 'Automatic zero for including Bill Gates in this. No, hold on there is no 0 vote, I''ll have to add 1 ...1 + 0 = 10: )', '2003-05-25 19:15:10.000000', NULL, 1),
