(306549, 21678, 4007, '<td valign="top">Unique.. and nice title.</td>', 'Unique.. and nice title.', '2003-05-25 22:06:13.000000', NULL, 1),
(306550, 22109, 4007, '<td valign="top">I''m sure you''re getting heckled with either  claims that this doesn''t fit the challenge, or claims that it''s offensive to equate christianity to the matrix, but I will say that among a lot of flashy shots, this one actually issues a challenge of beilefs and perceptions, which is always valuable, and which was a big part of the movie as well.</td>', 'I''m sure you''re getting heckled with either  claims that this doesn''t fit the challenge, or claims that it''s offensive to equate christianity to the matrix, but I will say that among a lot of flashy shots, this one actually issues a challenge of beilefs and perceptions, which is always valuable, and which was a big part of the movie as well.', '2003-05-25 22:08:18.000000', NULL, 1),
(306551, 22073, 4007, '<td valign="top">I like the grid-like appearance of the left hand pillars.</td>', 'I like the grid-like appearance of the left hand pillars.', '2003-05-25 22:08:54.000000', NULL, 1),
