(306558, 22152, 4007, '<td valign="top">I''ve always wondered what a chinese keyboard must look like.</td>', 'I''ve always wondered what a chinese keyboard must look like.', '2003-05-25 22:20:35.000000', NULL, 1),
(306569, 22212, 2586, '<td valign="top">Et ceci n''est pas Marcel Duchamps. I like the idea here to use the surrealists to convey the Matrix concept - a lot more original than all those sunglasses and blue and red pills. However, i find the execution of your creative idea lacking. You didn''t bother to rearrange your computer set up for this pose and it sets there, a bit clumsily for the picture, probably exactly as you always use it. The cardboard with the Ce n''est pas un ordinateur also sits there slightly awkwardly.  I don''t mean to come down so hard on you but the idea was excellent and you took the time to do the cardboard and approximate the font but then, unfortunately, you didn''t take the time to do the real shot. 6</td>', 'Et ceci n''est pas Marcel Duchamps. I like the idea here to use the surrealists to convey the Matrix concept - a lot more original than all those sunglasses and blue and red pills. However, i find the execution of your creative idea lacking. You didn''t bother to rearrange your computer set up for this pose and it sets there, a bit clumsily for the picture, probably exactly as you always use it. The cardboard with the Ce n''est pas un ordinateur also sits there slightly awkwardly.  I don''t mean to come down so hard on you but the idea was excellent and you took the time to do the cardboard and approximate the font but then, unfortunately, you didn''t take the time to do the real shot. 6', '2003-05-25 22:49:43.000000', NULL, 1),
(306570, 21809, 2586, '<td valign="top">Come on, this is just a screen capture. What does it have to do with photography? Boring. 1</td>', 'Come on, this is just a screen capture. What does it have to do with photography? Boring. 1', '2003-05-25 22:52:45.000000', NULL, 1),
