(306579, 22239, 7628, '<td valign="top">Refreshing and original - your own interpretation.  Lovely colors in a wholesome subject.  Wish the back apple had more dimension (back-lit as well?)  and the petals on the left would stand out even better with some back-light too.</td>', 'Refreshing and original - your own interpretation.  Lovely colors in a wholesome subject.  Wish the back apple had more dimension (back-lit as well?)  and the petals on the left would stand out even better with some back-light too.', '2003-05-25 23:00:49.000000', NULL, 1),
(306580, 21837, 4793, '<td valign="top">Nice photo, how did you shoot this? different, I like your shot</td>', 'Nice photo, how did you shoot this? different, I like your shot', '2003-05-25 23:02:52.000000', NULL, 1),
(306581, 21967, 2586, '<td valign="top">The creativity here consists of typing that phrase in a layer in Photoshop. Then you did a screencapture shot of it. Pretty lame, if you ask me. 3</td>', 'The creativity here consists of typing that phrase in a layer in Photoshop. Then you did a screencapture shot of it. Pretty lame, if you ask me. 3', '2003-05-25 23:03:08.000000', NULL, 1),
(306582, 21839, 7628, '<td valign="top">smarties or m&amp;ms?  Not quite what Morpheus offered up...but your own interpretation.  Nice close shot, simple.  perhaps a bit brightly lit.</td>', 'smarties or m&ms?  Not quite what Morpheus offered up...but your own interpretation.  Nice close shot, simple.  perhaps a bit brightly lit.', '2003-05-25 23:04:27.000000', NULL, 1),
(306584, 22084, 2586, '<td valign="top">With a suitable title, one can throw in the ubiquitous kiddie shot into ANY challenge. I''m really a softy on meeting-the-challenge except for something as creative as these overall Matrix submissions and i do punish kiddie shots when they are really totally off the wall. 3</td>', 'With a suitable title, one can throw in the ubiquitous kiddie shot into ANY challenge. I''m really a softy on meeting-the-challenge except for something as creative as these overall Matrix submissions and i do punish kiddie shots when they are really totally off the wall. 3', '2003-05-25 23:06:26.000000', NULL, 1),
